/bin/bash -lc "python3 - <<'PY'
import json
h=json.load(open('ensembl_sources/initial2/homo_sapiens_SHH_lookup.json'))
for tx in h['Transcript']:
    if tx['id']=='ENST00000297261':
        print(tx.keys())
        print('strand',tx['strand'],'start',tx['start'],'end',tx['end'],'is_canonical',tx.get('is_canonical'))
        print('translation',tx.get('Translation'))
        for e in sorted(tx['Exon'], key=lambda x:x['start']): print(e)
PY"

