/bin/bash -lc "python3 - <<'PY'
import json,re
j=json.load(open('ensembl_sources/final/ucsc_hg38_cactus241wayBM_chr7_155811822_155812122.json'))
names=set()
for item in j['cactus241wayBM']:
    for part in item['mafBlock'].replace('\\n',';').split(';'):
        part=part.strip()
        if part.startswith('s '):
            src=part.split()[1]
            if re.search('joh|sem|trach|lang|indri|ind',src,re.I):
                names.add(src)
for n in sorted(names): print(n)
print('all species matching first tokens')
prefixes=sorted({part.strip().split()[1].split('.')[0] for item in j['cactus241wayBM'] for part in item['mafBlock'].replace('\\n',';').split(';') if part.strip().startswith('s ')})
for p in prefixes:
    if re.search('Sem|Trach|Indri|joh',p,re.I): print(p)
PY"

